package dev.votex.config;
import java.util.*;
/** Deep copies preserve unsaved layouts and old absolute-coordinate records. */
public final class HudLayouts {
 public static final class Layout {public Map<String,Boolean> enabled=new LinkedHashMap<>();public Map<String,ModuleRegistry.Position> positions=new LinkedHashMap<>();public Map<String,ModuleRegistry.Appearance> appearance=new LinkedHashMap<>();public int scale=100;}
 public static void save(ModuleRegistry.Config c,String name){if(!name.matches("Layout [1-8]"))throw new IllegalArgumentException("Invalid layout name");var l=new Layout();l.enabled=new LinkedHashMap<>(c.enabled);l.positions=copyPositions(c.positions);l.appearance=copyAppearance(c.appearance);l.scale=c.scale;c.layouts.put(name,l);}
 public static boolean load(ModuleRegistry.Config c,String name){var l=c.layouts.get(name);if(l==null)return false;validate(l);c.positions=copyPositions(l.positions);c.appearance=copyAppearance(l.appearance);c.scale=l.scale;for(var module:ModuleRegistry.HUD_MODULES)c.enabled.put(module.id(),Boolean.TRUE.equals(l.enabled.get(module.id())));return true;}
 private static Map<String,ModuleRegistry.Position> copyPositions(Map<String,ModuleRegistry.Position> source){var result=new LinkedHashMap<String,ModuleRegistry.Position>();source.forEach((id,p)->{var v=new ModuleRegistry.Position(p.x,p.y);v.viewWidth=p.viewWidth;v.viewHeight=p.viewHeight;result.put(id,v);});return result;}
 private static Map<String,ModuleRegistry.Appearance> copyAppearance(Map<String,ModuleRegistry.Appearance> source){var result=new LinkedHashMap<String,ModuleRegistry.Appearance>();source.forEach((id,a)->{var v=new ModuleRegistry.Appearance();v.scale=a.scale;v.background=a.background;v.accent=a.accent;v.glassIntensity=a.glassIntensity;result.put(id,v);});return result;}
 public static void validate(Layout l){if(l==null||l.enabled==null||l.positions==null||l.appearance==null||l.scale<75||l.scale>150||l.positions.size()>64||l.appearance.size()>64)throw new IllegalArgumentException("Invalid HUD layout");for(var p:l.positions.values())if(p==null||p.x<0||p.y<0||p.x>10000||p.y>10000||p.viewWidth<0||p.viewWidth>10000||p.viewHeight<0||p.viewHeight>10000)throw new IllegalArgumentException("Invalid HUD coordinates");for(var a:l.appearance.values())if(a==null||a.scale<50||a.scale>200||a.background<0||a.background>100||a.glassIntensity<0||a.glassIntensity>100)throw new IllegalArgumentException("Invalid HUD appearance");}
 public static int resolve(int position,int oldSize,int newSize,int widgetSize){if(oldSize<=0)return position;return (int)Math.round(position/(double)Math.max(1,oldSize-widgetSize)*Math.max(1,newSize-widgetSize));}
 /** Edge/sibling snapping in the same coordinate space as the HUD; no hidden global grid. */
 public static int snap(int value,int size,int viewport,Collection<Integer> edges){int best=value,distance=7;for(int target:new int[]{4,(viewport-size)/2,viewport-size-4})if(Math.abs(value-target)<distance){distance=Math.abs(value-target);best=target;}for(int edge:edges)for(int target:new int[]{edge,edge-size,edge+6,edge-size-6})if(Math.abs(value-target)<distance){distance=Math.abs(value-target);best=target;}return best;}
}
